import{_ as a,o as t,c as i,a6 as n}from"./chunks/framework.CPCSkjM7.js";const p=JSON.parse('{"title":"Video Index After 2020","description":"","frontmatter":{},"headers":[],"relativePath":"projects/videoindex.md","filePath":"projects/videoindex.md","lastUpdated":1783535680000}'),r={name:"projects/videoindex.md"};function s(o,e,l,c,d,h){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="video-index-after-2020" tabindex="-1">Video Index After 2020 <a class="header-anchor" href="#video-index-after-2020" aria-label="Permalink to “Video Index After 2020”">​</a></h1><h2 id="_2025-2026" tabindex="-1">2025 - 2026 <a class="header-anchor" href="#_2025-2026" aria-label="Permalink to “2025 - 2026”">​</a></h2><h2 id="brayden-kirkland-puzzleheart-a-video-game-for-thinkers" tabindex="-1">Brayden Kirkland - Puzzleheart: A Video Game for Thinkers <a class="header-anchor" href="#brayden-kirkland-puzzleheart-a-video-game-for-thinkers" aria-label="Permalink to “Brayden Kirkland - Puzzleheart: A Video Game for Thinkers”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=08HqcfVhTII" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: Puzzleheart is a procedurally generated puzzle game developed in Unreal Engine 5 by Brayden M. Kirkland as a senior portfolio project, with the goal of creating an engaging experience that promotes logical reasoning, problem-solving, and critical thinking. The game features dynamically generated worlds containing puzzles that challenge memory, perception, and analytical skills while ensuring each playthrough remains unique and solvable. Core systems include player movement, environmental interaction, inventory management, procedural world generation, configurable settings, and multiple puzzle types. A structured testing process evaluated gameplay functionality, puzzle solvability, and user experience through repeated playthroughs using identical world seeds, demonstrating that players completed subsequent runs more efficiently as they gained familiarity with the game’s mechanics. Despite challenges associated with limited prior game development experience, the project successfully achieved its design objectives and highlights the potential of video games as tools for fostering cognitive skills while providing entertainment.</li></ul><h2 id="james-wood-fallout-76-companion" tabindex="-1">James Wood - Fallout 76 Companion <a class="header-anchor" href="#james-wood-fallout-76-companion" aria-label="Permalink to “James Wood - Fallout 76 Companion”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=6bQTElr4ZK4" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>:The Fallout 76 Companion App is a multi-tool application developed to improve player interaction with the complex systems of the online game Fallout 76. The project addresses the challenge of players making important gameplay decisions without clear access to character build information, map data, and time-sensitive activities. To solve this problem, the application integrates three primary tools: a build simulator for managing SPECIAL attributes, perk cards, legendary perks, and mutations; a cartography index for creating and organizing custom map markers and notes; and a daily activity tracker that consolidates event timers and location information. By centralizing these previously fragmented systems into a single interface, the application enhances information accessibility, supports more informed decision-making, reduces gameplay friction, and improves the overall user experience. The project demonstrates the practical application of software design principles to create an organized, user-focused solution for managing complex game mechanics.</li></ul><h2 id="andrew-burbage-discreet-dispatch" tabindex="-1">Andrew Burbage - Discreet Dispatch <a class="header-anchor" href="#andrew-burbage-discreet-dispatch" aria-label="Permalink to “Andrew Burbage - Discreet Dispatch”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=XsuBwvjje1Q" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: Discreet Dispatch is a mobile application designed to facilitate silent emergency reporting by enabling users to communicate critical information to emergency dispatchers without speaking. Developed using Kotlin and JavaScript, the application guides users through a series of responder-specific questions similar to those asked during a 911 call, collecting details about the emergency, individuals involved, and situational context. User responses are automatically compiled into a structured script and converted into a text-to-speech recording, which is then played during an automated phone call to emergency services. By providing an alternative communication method for individuals who are unable to speak safely or effectively during an emergency, the system improves accessibility, enhances dispatcher awareness, and supports faster, more informed deployment of first responders. The project demonstrates the application of mobile software development, user-centered design, and emergency communication principles to address a critical public safety need.</li></ul><h2 id="melody-cabanellas-stay-on-track-web-app" tabindex="-1">Melody Cabanellas - Stay on Track Web App <a class="header-anchor" href="#melody-cabanellas-stay-on-track-web-app" aria-label="Permalink to “Melody Cabanellas - Stay on Track Web App”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=J4PZEZ_DwQE" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: The Stay on Track web application is a productivity and task-management system designed to help users organize infrequent but important life-related responsibilities, such as appointments, maintenance schedules, deadlines, and license renewals. Developed as a senior project using Ruby on Rails, JavaScript, and HTML/CSS, the application addresses limitations of traditional task trackers that primarily focus on academic or daily activities. Key features include recurring task scheduling, customizable categories, priority and urgency management, deadline tracking, task completion monitoring, user accounts, and accessibility options such as theme customization. The system provides a dashboard that organizes tasks into overdue, upcoming, and completed sections, helping users prioritize responsibilities and avoid missed obligations. User acceptance testing and iterative refinement were used to evaluate usability, visual design, and functionality, resulting in improvements based on participant feedback. The project demonstrates the application of full-stack web development principles to create a practical tool that supports long-term organization and personal productivity.</li></ul><h2 id="raul-cabanellas-task-manager" tabindex="-1">Raul Cabanellas - Task Manager <a class="header-anchor" href="#raul-cabanellas-task-manager" aria-label="Permalink to “Raul Cabanellas - Task Manager”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=mEiEG75aIbY" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: The Task Manager project is a desktop scheduling and productivity application developed in C++ using Qt Creator to help users efficiently organize, prioritize, and track their tasks. The system enables users to create, edit, delete, and schedule tasks while assigning priorities, tracking completion status, linking prerequisite tasks, and organizing work into customizable groups. Designed with a simple and intuitive interface, the application provides multiple viewing modes, including weekly, monthly, and list-based schedules, along with drag-and-drop task management and visual indicators for task relationships and progress. The project emphasizes reducing the time required to manage complex schedules by offering clear organizational tools and quick task adjustments. Comprehensive testing against functional, usability, and interface requirements demonstrated successful implementation of all planned features, while peer feedback identified opportunities for future enhancements such as responsive design, mobile compatibility, personalization options, and advanced project-management visualizations. Overall, the project demonstrates the application of software engineering principles, user-centered design, and GUI development to create an effective task management solution.</li></ul><h2 id="helmut-cespedes-meet-me-in-the-middle" tabindex="-1">Helmut Cespedes - Meet Me in the Middle <a class="header-anchor" href="#helmut-cespedes-meet-me-in-the-middle" aria-label="Permalink to “Helmut Cespedes - Meet Me in the Middle”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=HjO_U9W6U_Y" target="_blank" rel="noreferrer"><strong>Video</strong></a></li></ul><h2 id="kailey-owens-personally-manage" tabindex="-1">Kailey Owens - Personally Manage <a class="header-anchor" href="#kailey-owens-personally-manage" aria-label="Permalink to “Kailey Owens - Personally Manage”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=5KW75cQleiU" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>:The Personal Management Application, “Personally Manage,” is a web-based productivity tool developed by Kailey Owens to help users organize daily responsibilities, reduce stress, and improve time management through a centralized platform. Built using Python, Flask, SQLite, HTML/CSS, JavaScript, and Jinja, the application integrates three primary features: a calendar for scheduling events and reminders, a notes section for capturing ideas and information, and a budgeting tool for managing personal finances. The system emphasizes ease of use through intuitive navigation, customizable scheduling, and accessible design, allowing users to efficiently track tasks, appointments, and financial goals. User testing indicated that different individuals found value in different features, demonstrating the application’s flexibility in meeting diverse personal management needs. The project also provided experience with web development, database integration, and user interface design, while establishing a foundation for future enhancements such as event alerts and expanded budgeting functionality.</li></ul><h2 id="marina-skegro-gamified-habit-tracker" tabindex="-1">Marina Skegro - Gamified Habit Tracker <a class="header-anchor" href="#marina-skegro-gamified-habit-tracker" aria-label="Permalink to “Marina Skegro - Gamified Habit Tracker”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=Wc1zbJ82FM0" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: Habit Love is a gamified habit-tracking app built with Flutter and Firebase. The app transforms the often dull process of building new habits into an engaging, rewarding experience where users earn XP for completing daily habits, level up as they grow, and unlock achievement badges for hitting milestones. Streaks keep users accountable day over day, while a built-in analytics dashboard visualizes progress through weekly and monthly charts so users can actually see themselves improving over time. All data syncs to the cloud in real time via Firebase, meaning progress is never lost and is accessible across devices. The result is an app designed to make habit formation more engaging and sustainable.</li></ul><h2 id="christian-green-learnnow-interactive-learning-web-app" tabindex="-1">Christian Green - LearnNow Interactive Learning Web app <a class="header-anchor" href="#christian-green-learnnow-interactive-learning-web-app" aria-label="Permalink to “Christian Green - LearnNow Interactive Learning Web app”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=rPzuvlZWswY" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: LearnNow is an interactive educational web application designed to make learning engaging and accessible for elementary school students. Developed using React, Node.js, MySQL, TailwindCSS, and C#, the platform allows users to create accounts, track academic progress, and participate in personalized learning paths focused on subjects such as elementary mathematics and geometry. The system includes features such as secure authentication, password recovery, real-time progress tracking through a backend API, user-to-user chat functionality, leaderboards, and customizable themes. To enhance engagement, the platform incorporates educational games that reinforce concepts learned through lessons and assessments. By combining interactive learning tools, progress monitoring, and social features, LearnNow provides a comprehensive environment that supports both academic development and user engagement.</li></ul><h2 id="michael-ludwikowski-stock-trading-ai-analyst" tabindex="-1">Michael Ludwikowski - Stock Trading AI Analyst <a class="header-anchor" href="#michael-ludwikowski-stock-trading-ai-analyst" aria-label="Permalink to “Michael Ludwikowski - Stock Trading AI Analyst”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=UoYlHUVdPDQ" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: The Stock Trading AI Analyst is an educational web-based platform designed to help beginner investors learn stock market concepts and trading strategies in a safe, simulated environment. Developed by Michael Ludwikowski using Python, Flask, SQLite, HTML/CSS, JavaScript, Bokeh, and Ollama (Llama 3.2), the application combines paper trading, portfolio management, real-time market data, interactive visualizations, and AI-generated investment guidance. Users can practice buying and selling stocks with virtual funds, monitor portfolio performance, explore historical market data, and receive AI-assisted buy, sell, or hold recommendations that include confidence levels and risk assessments. The platform also features practice and simulation modes, educational resources, and persistent account tracking to reinforce learning through hands-on experience. By integrating financial education, data visualization, and artificial intelligence, the project provides a realistic yet risk-free environment for developing trading knowledge and decision-making skills.</li></ul><h2 id="peter-jackson-link-project-charito-biblical-research-tool" tabindex="-1">Peter Jackson Link - Project Charito: Biblical Research Tool <a class="header-anchor" href="#peter-jackson-link-project-charito-biblical-research-tool" aria-label="Permalink to “Peter Jackson Link - Project Charito: Biblical Research Tool”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=AHa8HADG9WE" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: Project Charito is a web-based biblical research platform designed to provide free, public-domain resources for Bible study, church history research, and original-language analysis. The system integrates multiple English Bible translations, Greek and Hebrew texts, commentaries, and writings of the Church Fathers into a hypertext-driven interface that emphasizes accessibility and scholarly exploration. Built primarily in Common Lisp using the AP5 knowledge-base system, Charito employs custom data structures and automated ingestion of theological XML sources to manage large volumes of interconnected scripture references and historical documents. Key features include scripture search, lexical and grammatical analysis, cross-referencing between biblical texts and historical sources, user accounts with note-taking capabilities, manuscript comparison tools, and customizable reading settings. The project is deployed on an OpenBSD-based infrastructure using lightweight web technologies and has demonstrated successful automated testing and positive user feedback. Future development focuses on expanding resource integration, enhancing lexicon support, improving documentation, and enabling collaborative study features.</li></ul><h2 id="daniel-howard-noah-huber-swiftedge-security-optimizer" tabindex="-1">Daniel Howard &amp; Noah Huber - SwiftEdge Security &amp; Optimizer <a class="header-anchor" href="#daniel-howard-noah-huber-swiftedge-security-optimizer" aria-label="Permalink to “Daniel Howard &amp; Noah Huber - SwiftEdge Security &amp; Optimizer”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=L4otDR-b38M" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: SwiftEdge Security &amp; Optimizer was created to provide a single Windows utility that combines performance tuning, lightweight security hardening, system cleanup, and vulnerability scanning inside one graphical application. The project was intended to reduce the need for separate scripts, third-party applications, built-in utilities, and manual registry or service changes by grouping practical maintenance and security actions into a single PowerShell-based Windows Forms application.</li></ul><h2 id="kayla-dixon-audio-player-with-speed-and-pitch-adjustments" tabindex="-1">Kayla Dixon - Audio Player with Speed and Pitch Adjustments <a class="header-anchor" href="#kayla-dixon-audio-player-with-speed-and-pitch-adjustments" aria-label="Permalink to “Kayla Dixon - Audio Player with Speed and Pitch Adjustments”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=LrtfD8wUhCk" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: This project will be an app designed to change the pitch, tempo, and length of music on your mobile device while functioning as a music player.</li></ul><h2 id="teaundra-thompson-multi-layer-perceptron-based-intrusion-detection-system" tabindex="-1">Teaundra Thompson - Multi-Layer Perceptron-Based Intrusion Detection System <a class="header-anchor" href="#teaundra-thompson-multi-layer-perceptron-based-intrusion-detection-system" aria-label="Permalink to “Teaundra Thompson - Multi-Layer Perceptron-Based Intrusion Detection System”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=U-ZhdGiMMXE" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: A Multi-Layer Perceptron model that has been trained on the UFWZeekData24 dataset, and the results from the test cases.</li></ul><h2 id="logan-riley-gizmo-ai-powered-meccanoid-robot-assistant" tabindex="-1">Logan Riley - Gizmo: AI-Powered Meccanoid Robot Assistant <a class="header-anchor" href="#logan-riley-gizmo-ai-powered-meccanoid-robot-assistant" aria-label="Permalink to “Logan Riley - Gizmo: AI-Powered Meccanoid Robot Assistant”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=_mU7KozTma0" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: The project is a backend development assignment in which students design and implement a full backend system that supports multiple user stories through a unified architecture. It emphasizes translating prior requirements and development specifications into a working, scalable backend, including clear module design, data abstractions, persistent storage, and well-defined APIs (often REST-based). The project also requires system-level thinking, such as coordinating multiple backend components, ensuring concurrency support, and documenting architectural decisions with diagrams (e.g., Mermaid). In addition to implementation, students must provide detailed documentation of their design process, justify engineering choices, and include evidence of testing and correctness. Overall, the project focuses on applying software engineering principles to build a coherent, maintainable backend while demonstrating the ability to move from specification to production-ready system design.</li></ul><h2 id="whitney-carpenter-securepass-chrome-extension" tabindex="-1">Whitney Carpenter - SecurePass Chrome Extension <a class="header-anchor" href="#whitney-carpenter-securepass-chrome-extension" aria-label="Permalink to “Whitney Carpenter - SecurePass Chrome Extension”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=QrieWGQJ3Rw" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: A user-friendly extension to evaluate password strength and provide instant feedback will enhance online security and protect user privacy. Ideally, users would create strong, complex passwords adhering to the highest security standards; however, many struggle with this, opting for simple, reused passwords. This is a critical issue as weak passwords create significant security risks, including hacking attempts, data breaches, and identity theft, potentially leading to financial loss, privacy invasion, and reputational damage. According to the Verizon Data Breach Investigations Report¹, 81% of hacking-related breaches involve compromised and weak passwords. Using a user-friendly Chrome extension to evaluate password strength will significantly mitigate these risks. Users stand to benefit substantially from this extension in the form of enhanced security and the support of their right to privacy. Weak passwords are a major security risk that can lead to significant consequences, but by developing a user-friendly Chrome extension that evaluates password strength and provides instant, local feedback, we can help users create stronger passwords, enhance their online security, and protect their privacy. This project was completed as part of an Honors Senior Project, requiring additional implementation effort, including preparing the extension for real-world deployment and meeting elevated documentation and testing standards.</li></ul><h2 id="laura-kirby-web-server-solution" tabindex="-1">Laura Kirby - Web Server Solution <a class="header-anchor" href="#laura-kirby-web-server-solution" aria-label="Permalink to “Laura Kirby - Web Server Solution”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=oqJFLW1C070" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: This project is the design, proposal, and implementation of a web server solution for the Charleston Southern University Computer Science department. The goal for this project is to design a solution for students and faculty to host the websites that they design and are needed to complete various coursework, without independently researching and purchasing hosting services on various sites. This will be accomplished through an IT decision process that considers cost, functionality, longevity, and its support and maintainability. This solution will provide for up to one hundred fifty websites to give students and faculty the ability to easily manage the hosting of their various coursework. Furthermore, it will give cohesiveness to the department to have websites all hosted the same way and serve as an opportunity for students to develop professional skills by deploying websites.</li></ul><h2 id="logan-reed-cisco-packet-tracer" tabindex="-1">Logan Reed - Cisco Packet Tracer <a class="header-anchor" href="#logan-reed-cisco-packet-tracer" aria-label="Permalink to “Logan Reed - Cisco Packet Tracer”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=m7mtLSocd4U" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: It is a lab that guides the user on how to use Cisco Packet Tracer to create and secure a small network.</li></ul><h2 id="jacob-nagle-cyber-math" tabindex="-1">Jacob Nagle - Cyber Math <a class="header-anchor" href="#jacob-nagle-cyber-math" aria-label="Permalink to “Jacob Nagle - Cyber Math”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=8qpuYyvr3Us" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: This project involves the design and development of a safe, interactive website that will be made to help fourth-grade students improve their multiplication and division skills. The website will offer a fun and educational experience through a variety of features such as timed challenges, game-like quizzes, and progress tracking. The main goal is to help students build math fluency while also promoting cybersecurity safety habits.</li></ul><h2 id="joshua-strafford-game-winning-stats-webapp" tabindex="-1">Joshua Strafford - Game-Winning Stats Webapp <a class="header-anchor" href="#joshua-strafford-game-winning-stats-webapp" aria-label="Permalink to “Joshua Strafford - Game-Winning Stats Webapp”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=2GZJQ1qUHN4" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: This project is a sports analytics website that collects, processes, and displays player statistics from multiple sources. Some key features include web scraping from: Basketball Reference, Baseball Reference, and ESPN. There is data transformation into structured JSON files and dataframes, player search functionality, and player profile pages, including career stats, advanced analytics, rankings/comparisons, and visualization of stats in charts/graphs.</li></ul><h2 id="joshua-ingalls-cyber-range-expansion-for-beginners" tabindex="-1">Joshua Ingalls - Cyber-Range Expansion for Beginners <a class="header-anchor" href="#joshua-ingalls-cyber-range-expansion-for-beginners" aria-label="Permalink to “Joshua Ingalls - Cyber-Range Expansion for Beginners”">​</a></h2><ul><li><a href="https://www.youtube.com/watch?v=F1m6z-3uLXA" target="_blank" rel="noreferrer"><strong>Video</strong></a></li><li><strong>Abstract</strong>: A virtual environment where Freshman/Sophomore Cybersecurity students can learn the basic principles needed for cyber competitions. Students will be able to enumerate and explore networks, navigate Command Line Interfaces, and establish firewall rules against attacking IP.</li></ul>',44)])])}const g=a(r,[["render",s]]);export{p as __pageData,g as default};
